<?php use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V;
$cats = ['' => 'Todas']; foreach (H::categories() as $c) { $cats[$c['id']] = $c['name']; }
$agents = ['' => 'Todos', 'none' => 'Sem responsável']; foreach (H::agents() as $a) { $agents[$a['user_id']] = trim($a['first_name'] . ' ' . $a['last_name']); } ?>
<div class="cms-card"><?php if ($showFilters): ?><form class="cms-filters" method="get"><?= V::field('Protocolo, assunto ou e-mail', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::TICKET_STATUS]) ?><?= V::field('Prioridade', 'priority', $filters['priority'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::PRIORITIES]) ?><?= V::field('Categoria', 'category', $filters['category'], ['type' => 'select', 'choices' => $cats]) ?><?= V::field('Responsável', 'assignee', $filters['assignee'], ['type' => 'select', 'choices' => $agents]) ?><?= V::field('Tag', 'tag', $filters['tag']) ?><?= V::field('Prazo', 'overdue', $filters['overdue'], ['type' => 'select', 'choices' => ['' => 'Todos', '1' => 'Vencidos']]) ?><button class="cms-btn">Filtrar</button></form><?php endif; ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum chamado encontrado.') ?><?php else: ?><form method="post" action="/acao/ticket-bulk-status" data-confirm="Alterar a situação dos chamados selecionados?"><?= V::csrf() ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Chamados"><table><thead><tr><th><span class="cms-sr">Selecionar</span></th><th>Protocolo</th><th>Assunto</th><th>Cliente</th><th>Categoria</th><th>Prioridade</th><th>Situação</th><th>Responsável</th><th>Prazo</th></tr></thead><tbody><?php foreach ($result['rows'] as $t): $sla = H::slaLabel($t); ?><tr><td><input type="checkbox" name="ids[]" value="<?= (int) $t['id'] ?>" aria-label="Selecionar <?= V::e($t['protocol']) ?>"></td><td><a href="/chamados/<?= (int) $t['id'] ?>"><?= V::e($t['protocol']) ?></a></td><td><?= V::e($t['subject']) ?></td><td><?= V::e($t['requester_email']) ?></td><td><?= V::e($t['category_name']) ?></td><td><?= V::badge($t['priority'], V::PRIORITIES[$t['priority']] ?? $t['priority']) ?></td><td><?= V::badge($t['status'], V::TICKET_STATUS[$t['status']] ?? $t['status']) ?></td><td><?= V::e($t['assignee_name'] ?? '—') ?></td><td><?= $sla === 'Vencido' ? V::badge('overdue', $sla) : V::e($sla) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if (\Moves\Services\CmsAuth::can($admin, 'tickets.reply')): ?><div class="cms-filters cms-bulk"><?= V::field('Com os selecionados', 'status', '', ['type' => 'select', 'choices' => V::TICKET_STATUS]) ?><button class="cms-btn">Aplicar</button></div><?php endif; ?></form><?= V::pager($result) ?><?php endif; ?></div>
